if (!defined('ABSPATH')) { exit; }
// Native blocks keep presentation copy editable; operational lists remain dynamic.
function awsw_home_blocks($ur = false) {
    $t = function($en,$urdu) use ($ur) { return $ur ? $urdu : $en; };
    $heading = function($text,$level=2) { return '<!-- wp:heading {"level":'.$level.'} --><h'.$level.' class="wp-block-heading">'.$text.'</h'.$level.'><!-- /wp:heading -->'; };
    $para = function($text,$class='') { return '<!-- wp:paragraph'.($class?' {"className":"'.$class.'"}':'').' --><p'.($class?' class="'.$class.'"':'').'>'.esc_html($text).'</p><!-- /wp:paragraph -->'; };
    $shortcode = function($name) { return '<!-- wp:shortcode -->'.$name.'<!-- /wp:shortcode -->'; };
    $button = function($text,$slug) use($ur) { return '<!-- wp:buttons --><div class="wp-block-buttons"><!-- wp:button {"className":"awsw-native-button"} --><div class="wp-block-button awsw-native-button"><a class="wp-block-button__link wp-element-button" href="'.esc_url(add_query_arg('lang',$ur?'ur':'en',home_url('/'.$slug.'/'))).'">'.esc_html($text).' ↗</a></div><!-- /wp:button --></div><!-- /wp:buttons -->'; };
    $group = function($html,$class) { return '<!-- wp:group {"className":"'.$class.'"} --><div class="wp-block-group '.$class.'">'.$html.'</div><!-- /wp:group -->'; };
    $left=$para($t('PEOPLE FIRST. ALWAYS.','انسانیت سب سے پہلے۔ ہمیشہ۔'),'awsw-eyebrow').$heading($t('Together, we make<br>essential needs<br><em>accessible.</em>','مل کر بنیادی<br>ضروریات تک رسائی<br><em>آسان بنائیں۔</em>'),1).$para($t('Food on the table. A chance to learn. Clean water and essential care. Help build the possibilities every community deserves.','دسترخوان پر کھانا، سیکھنے کا موقع، صاف پانی اور ضروری علاج۔ ہر برادری کے لیے بہتر امکانات کی تعمیر میں ساتھ دیں۔')).$button($t('Donate Now','ابھی عطیہ دیں'),'donate').$para($t('Community care in Pakistan · Contributions in PKR','پاکستان میں اجتماعی بہبود · پاکستانی روپے میں عطیات'),'awsw-small').$button($t('Explore Our Work','ہمارا کام دیکھیں'),'programs');
    $right='<!-- wp:html --><div class="awsw-hero-art"><span class="awsw-art-label">'.esc_html($t('ROOTED IN KINDNESS','ہمدردی ہماری بنیاد')).'</span><span class="awsw-art-flower" aria-hidden="true">✳</span><div class="awsw-art-title">'.wp_kses($t('Care.<br>Opportunity.<br><em>Possibility.</em>','ہمدردی۔<br>موقع۔<br><em>امکان۔</em>'),['br'=>[],'em'=>[]]).'</div><p>'.esc_html($t('Approved AWS Welfare photograph to be added. This illustration is not evidence of project activity.','منظور شدہ تصویر جلد شامل ہو گی۔ یہ خاکہ عملی سرگرمی کا ثبوت نہیں۔')).'</p><div class="awsw-art-seal" aria-hidden="true">♡</div></div><!-- /wp:html -->';
    $html=$group($group($left,'awsw-hero-copy').$right,'awsw-hero');
    $html.=$group($para($t('Dignity · Community care · Accountability','عزت · اجتماعی معاونت · جواب دہی')),'awsw-values');
    $html.=$group($para($t('FOUR ESSENTIALS. ONE SHARED PURPOSE.','چار بنیادی شعبے۔ ایک مشترکہ مقصد۔'),'awsw-eyebrow').$heading($t('Many ways to care. <em>A place for everyone.</em>','خدمت کے کئی راستے۔ <em>ہر ایک کے لیے جگہ۔</em>')).$shortcode('[awsw_programs]'),'awsw-section');
    $html.=$group($heading($t('Explore active campaigns','جاری مہمات دیکھیں')).$shortcode('[awsw_featured]').$button($t('All campaigns','تمام مہمات'),'campaigns'),'awsw-section awsw-soft');
    $html.=$group($para($t('EVIDENCE BEFORE NUMBERS','اعداد سے پہلے ثبوت'),'awsw-eyebrow').$heading($t('Impact you can understand.','اثرات، واضح انداز میں۔')).$shortcode('[awsw_metrics]').$heading($t('How your support is used','آپ کا تعاون کیسے استعمال ہوتا ہے')).$para($t('Campaigns explain assessed needs and intended use of funds. Staff verify contributions against bank statements. Dated delivery milestones and reviewed reports document progress separately from fundraising.','مہمات میں ضروریات اور رقم کا متوقع استعمال بیان ہوتا ہے۔ عملہ بینک اسٹیٹمنٹ سے عطیات کی تصدیق کرتا ہے۔ تاریخ وار عملی مراحل اور جائزہ شدہ رپورٹس عطیات سے الگ پیش رفت بیان کرتے ہیں۔')),'awsw-section');
    $html.=$group($heading($t('Updates from our work','ہمارے کام کی خبریں')).$shortcode('[awsw_updates]').$button($t('All updates','تمام خبریں'),'impact'),'awsw-section awsw-soft');
    $html.=$group($group($heading($t('Good work deserves <em>clear reporting.</em>','اچھا کام، <em>واضح رپورٹنگ کے ساتھ۔</em>')).$para($t('Understand how contributions are recorded and used. Approved reports are published with reporting periods.','جانیں کہ عطیات کیسے درج اور استعمال ہوتے ہیں۔ منظور شدہ رپورٹس مدت کے ساتھ شائع ہوتی ہیں۔')).$button($t('Transparency & reports','شفافیت اور رپورٹس'),'transparency'),'awsw-transparency-intro').$group($heading($t('Give your time. <em>Grow the good.</em>','اپنا وقت دیں۔ <em>بھلائی بڑھائیں۔</em>')).$para($t('Share your skills and care. Tell the team how you would like to help.','اپنی مہارت اور ہمدردی بانٹیں۔ ٹیم کو بتائیں کہ آپ کیسے مدد کرنا چاہیں گے۔')).$button($t('Become a volunteer','رضاکار بنیں'),'volunteer'),'awsw-volunteer-panel'),'awsw-section awsw-split');
    $faq=$heading($t('Before you give.','عطیہ دینے سے پہلے۔'));
    foreach([['How can I donate?','میں عطیہ کیسے دوں؟','Use verified bank details on the Donate page. Transfer through your bank, then submit the reference for review.','عطیات کے صفحے پر تصدیق شدہ بینک معلومات دیکھیں، اپنے بینک سے ٹرانسفر کریں اور حوالہ جائزے کے لیے بھیجیں۔'],['Does submitting confirm payment?','کیا درخواست سے ادائیگی کی تصدیق ہوتی ہے؟','No. Only donations matched to settled bank transactions are confirmed.','نہیں۔ صرف بینک ٹرانزیکشن سے ملنے والے عطیات تصدیق شدہ ہوتے ہیں۔'],['Can I stay anonymous?','کیا شناخت پوشیدہ رکھی جا سکتی ہے؟','Yes. Staff retain necessary details internally, and donor lists are not published.','جی ہاں۔ عملہ ضروری معلومات اندرونی طور پر رکھتا ہے؛ عطیہ دہندگان کی فہرستیں شائع نہیں کی جاتیں۔'],['Where are the reports?','رپورٹس کہاں ہیں؟','Visit Transparency for reviewed reports and honest explanations of missing information.','جائزہ شدہ رپورٹس اور غیر موجود معلومات کی وضاحت کے لیے شفافیت کا صفحہ دیکھیں۔']] as $f){$faq.='<!-- wp:details --><details class="wp-block-details"><summary>'.esc_html($t($f[0],$f[1])).'</summary>'.$para($t($f[2],$f[3])).'</details><!-- /wp:details -->';}
    $html.=$group($faq,'awsw-section awsw-faq');
    $html.=$group($para($t('KINDNESS IS SOMETHING WE BUILD TOGETHER','بھلائی ہم مل کر تعمیر کرتے ہیں'),'awsw-eyebrow').$heading($t('A better tomorrow <em>starts with us.</em>','بہتر کل کا آغاز <em>ہم سے ہوتا ہے۔</em>')).$button($t('Find your way to help','تعاون کا راستہ اپنائیں'),'donate'),'awsw-closing');
    return $html;
}
add_shortcode('awsw_featured',function(){return awsw_campaign_cards(['posts_per_page'=>3,'meta_key'=>'_awsw_status','meta_value'=>'active']);});
